// Cloudflare Workers entry for LinkOps. Wraps the worker generated by `opennextjs-cloudflare
// build` and adds a Cron Trigger handler (schedule in wrangler.jsonc) that runs the same daily
// job as Vercel Cron: it calls /api/cron/daily inside this Worker with CRON_SECRET, which the
// route verifies before doing anything.
import openNextWorker from "./.open-next/worker.js"

export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js"

const worker = {
  fetch: openNextWorker.fetch,

  async scheduled(controller, env, ctx) {
    if (!env.CRON_SECRET) {
      console.error("[cron] CRON_SECRET is not set; skipping scheduled job")
      return
    }
    const request = new Request("https://linkops.internal/api/cron/daily", {
      headers: { Authorization: `Bearer ${env.CRON_SECRET}` },
    })
    const response = await openNextWorker.fetch(request, env, ctx)
    const summary = await response.text()
    console.log(`[cron] ${controller.cron} -> ${response.status} ${summary.slice(0, 500)}`)
  },
}

export default worker
